package pzvrphysicality;

import viewpointvr.physics.CollisionShape;

/** Native render geometry expressed around the tracked hand's right/forward/up rigid basis. */
public final class HeldContactGeometry {
 public static float[] pose(WorldRigFrame.Hand hand){if(hand==null)throw new IllegalArgumentException("Held hand missing");double u=hand.units();var x=hand.right();var y=hand.forward();var z=hand.up();double[] m={x.x()/u,y.x()/u,z.x()/u,x.y()/u,y.y()/u,z.y()/u,x.height()/u,y.height()/u,z.height()/u};double det=m[0]*(m[4]*m[8]-m[5]*m[7])-m[1]*(m[3]*m[8]-m[5]*m[6])+m[2]*(m[3]*m[7]-m[4]*m[6]);if(Math.abs(det-1)>.01)throw new IllegalArgumentException("Held proper world basis");double qx,qy,qz,qw,trace=m[0]+m[4]+m[8];if(trace>0){double s=2*Math.sqrt(trace+1);qw=s/4;qx=(m[7]-m[5])/s;qy=(m[2]-m[6])/s;qz=(m[3]-m[1])/s;}else if(m[0]>m[4]&&m[0]>m[8]){double s=2*Math.sqrt(1+m[0]-m[4]-m[8]);qw=(m[7]-m[5])/s;qx=s/4;qy=(m[1]+m[3])/s;qz=(m[2]+m[6])/s;}else if(m[4]>m[8]){double s=2*Math.sqrt(1+m[4]-m[0]-m[8]);qw=(m[2]-m[6])/s;qx=(m[1]+m[3])/s;qy=s/4;qz=(m[5]+m[7])/s;}else{double s=2*Math.sqrt(1+m[8]-m[0]-m[4]);qw=(m[3]-m[1])/s;qx=(m[2]+m[6])/s;qy=(m[5]+m[7])/s;qz=s/4;}double norm=Math.sqrt(qx*qx+qy*qy+qz*qz+qw*qw);var p=hand.grip();return new float[]{(float)p.x(),(float)p.y(),(float)p.height(),(float)(qx/norm),(float)(qy/norm),(float)(qz/norm),(float)(qw/norm)};}
 public static CollisionShape shape(ItemMeshCpu.Data geometry,float[] matrix,WorldRigFrame rig,WorldRigFrame.Hand hand){if(geometry==null||rig==null||hand==null)throw new IllegalArgumentException("Held numeric source missing");var result=ItemMesh.fromRendered(geometry.vertices(),geometry.faces(),matrix,rig.camera().x(),rig.camera().y(),rig.camera().height()/Math.sqrt(6),pose(hand));float[] vertices=result.vertices();if(vertices.length>48000||result.faces().length>96000)throw new IllegalArgumentException("Held mesh budget");double radius=0;for(int n=0;n<vertices.length;n+=3)radius=Math.max(radius,Math.sqrt(vertices[n]*vertices[n]+vertices[n+1]*vertices[n+1]+vertices[n+2]*vertices[n+2]));if(radius<.005*hand.units()||radius>.75*hand.units())throw new IllegalArgumentException("Held prop contact extent");return result;}
 public static boolean sameMount(CollisionShape first,CollisionShape second,double units){if(first==null||second==null||!java.util.Arrays.equals(first.faces(),second.faces()))return false;float[] a=first.vertices(),b=second.vertices();if(a.length!=b.length)return false;for(int n=0;n<a.length;n++)if(Math.abs(a[n]-b[n])>.002*units)return false;return true;}
 private HeldContactGeometry(){}
}
